"use client";

import { loadFont } from "@remotion/google-fonts/SchibstedGrotesk";
import { type ReactNode, useId } from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_HIGHLIGHT,
  DEFAULT_LINE,
  type FractionSplitElementId,
  fractionSplitTimeline,
  LEVELS,
  splitWords,
} from "./timeline";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

// gradients.sh "fluted" palette
const FLUTED = {
  bg: "#050507",
  c: ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"],
} as const;

export interface FractionSplitProps {
  line?: string;
  highlight?: string;
  accentPiece?: number;
  accent?: string;
  /** Color of the line and the bar; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the line and labels. Load it yourself; Schibsted Grotesk by default. */
  fontFamily?: string;
  /** Frames between words as the line rises in. */
  stagger?: number;
  /** Corner radius of the bar pieces, in pixels at 1280×720. */
  radius?: number;
  /** Size of the foreground, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  grain?: boolean;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the push, the wipe, the splits, the regroup
   * and the words, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<FractionSplitElementId>;
}

const SEGS = 8;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const SPLIT_SPRING = { damping: 17, stiffness: 170, mass: 0.7 };

const THEMES = {
  dark: {
    bg: FLUTED.bg,
    fg: "#F3F2EF",
    muted: "#8B8A90",
    outline: "rgba(243,242,239,0.34)",
    hl: ["#6a9dff", FLUTED.c[2], "#ffb27e"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    outline: "rgba(18,18,20,0.34)",
    hl: [FLUTED.c[0], FLUTED.c[2], "#e85a26"],
    grain: 0.045,
  },
} as const;

function boundaryLevel(b: number) {
  if (b === 4) return 0;
  if (b === 2 || b === 6) return 1;
  return 2;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={37}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function FractionSplit(props: FractionSplitProps) {
  const {
    line = DEFAULT_LINE,
    highlight = DEFAULT_HIGHLIGHT,
    accentPiece = 0,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    radius = 8,
    scale = 1,
    delay = 0,
    grain = true,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    fractionSplitTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const splits = LEVELS.map((_, i) => tl.get(`split:${i}`));
  const regEl = tl.get("regroup");
  const wipeEl = tl.get("wipe");
  const pushEl = tl.get("push");
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const ap = Math.max(0, Math.min(SEGS - 1, Math.round(accentPiece)));

  const cx = width / 2;
  const cy = height / 2;
  const barW = Math.min(width * 0.8, 1040 * u);
  const barH = 116 * u;
  const G = 14 * u;
  const R = radius * u;
  const E = 3 * G;
  const textSize = 96 * u;
  const textLines = line.length * 0.43 * textSize > barW * 0.98 ? 2 : 1;
  const textH = textSize * textLines * 1.02;
  const textGap = 58 * u;
  const finalTop = cy - (barH + textGap + textH) / 2;

  // The bar's geometry at any time; `settled` is where every piece lands.
  const geometry = (tt: number, settled = false) => {
    const open: number[] = [0];
    for (let b = 1; b < SEGS; b++) {
      const lv = splits[boundaryLevel(b)];
      const stagger = Math.abs(b - 4) * lv.beat("spread");
      open.push(
        settled
          ? 1
          : spring({
              frame: tt - lv.start - stagger,
              fps,
              config: SPLIT_SPRING,
            }),
      );
    }
    const totalGap = open.reduce((s, x) => s + x, 0) * G;
    const segW = (barW - totalGap) / SEGS;
    const reg = settled
      ? 1
      : interpolate(tt, [regEl.start, regEl.end], [0, 1], {
          ...CLAMP,
          easing: EASE_IO,
        });
    const left = cx - barW / 2 - (E / 2) * reg;
    const xs: number[] = [];
    let acc = left;
    for (let j = 0; j < SEGS; j++) {
      if (j > 0) acc += open[j] * G;
      xs.push(acc + (j > ap ? E * reg : 0));
      acc += segW;
    }
    const top = cy - barH / 2 + (finalTop - (cy - barH / 2)) * reg;
    return { open, segW, reg, xs, top };
  };
  const { open, segW, reg, xs, top } = geometry(t);
  const before = geometry(t - speed);
  const after = geometry(t + speed);
  const landed = geometry(t, true);
  const rise = interpolate(
    t,
    [regEl.start, regEl.start + regEl.beat("rise")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const drainOf = (j: number) => {
    const order = j > ap ? j - 1 : j;
    return interpolate(
      t,
      [
        regEl.start + regEl.beat("drainAt") + order * regEl.beat("drainStep"),
        regEl.start + regEl.beat("drainEnd") + order * regEl.beat("drainStep"),
      ],
      [0, 1],
      { ...CLAMP, easing: EASE_IO },
    );
  };

  const wipe = interpolate(t, [wipeEl.start, wipeEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const runs: { j0: number; j1: number }[] = [];
  for (let j = 0; j < SEGS; j++) {
    const solo = reg > 0 || j === 0 || open[j] > 0.002;
    if (solo) runs.push({ j0: j, j1: j });
    else runs[runs.length - 1].j1 = j;
  }

  const cornerAt = (b: number) =>
    b <= 0 || b >= SEGS ? R : R * Math.min(1, open[b] * 1.6 + reg);

  const labelStyle = {
    position: "absolute",
    left: 14 * u,
    fontFamily,
    fontWeight: 500,
    fontSize: 20 * u,
    lineHeight: 1.2,
    letterSpacing: "-0.01em",
    fontVariantNumeric: "tabular-nums",
    whiteSpace: "nowrap",
  } as const;
  const lastLabel = LEVELS[LEVELS.length - 1].label;
  const drift = interpolate(
    t,
    [regEl.start, regEl.start + regEl.beat("drift")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  // the palette's blue stop follows the accent prop
  const blue = accent;
  const flute = (deg: number) =>
    `linear-gradient(${deg + 12 * drift}deg, ${FLUTED.c[3]} 0%, ${FLUTED.c[2]} 30%, ${blue} 68%, ${FLUTED.c[0]} 100%)`;

  const pieces = runs.map(({ j0, j1 }) => {
    const x = xs[j0];
    const w = xs[j1] + segW - x;
    const rl = cornerAt(j0);
    const rr = cornerAt(j1 + 1);
    // While a piece travels it is laid out where it lands and the way there
    // is a transform: layout rounds a box to whole pixels, so a piece eased
    // by `left`/`top` clicks along pixel by pixel. At rest it keeps its plain
    // layout.
    const moving =
      Math.abs(after.xs[j0] - x) > 1e-3 ||
      Math.abs(x - before.xs[j0]) > 1e-3 ||
      Math.abs(after.top - top) > 1e-3 ||
      Math.abs(top - before.top) > 1e-3;
    const box = {
      position: "absolute",
      left: moving ? landed.xs[j0] : x,
      top: moving ? landed.top : top,
      transform: moving
        ? `translate(${x - landed.xs[j0]}px, ${top - landed.top}px)`
        : undefined,
      width: w,
      height: barH,
      borderTopLeftRadius: rl,
      borderBottomLeftRadius: rl,
      borderTopRightRadius: rr,
      borderBottomRightRadius: rr,
    } as const;
    if (reg <= 0) {
      return <div key={`p${j0}-${j1}`} style={{ ...box, background: fg }} />;
    }
    const isAccent = j0 === ap;
    const fillH = barH * (isAccent ? rise : 1 - drainOf(j0));
    return (
      <div key={`p${j0}-${j1}`}>
        {isAccent ? null : (
          <div
            style={{
              ...box,
              boxSizing: "border-box",
              border: `${Math.max(1, 1.5 * u)}px solid ${p.outline}`,
            }}
          />
        )}
        <div
          style={{
            ...box,
            overflow: "hidden",
            background: isAccent ? fg : "transparent",
          }}
        >
          {isAccent ? (
            <div style={{ ...labelStyle, top: 12 * u, color: p.bg }}>
              {lastLabel}
            </div>
          ) : null}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: 0,
              height: fillH,
              overflow: "hidden",
              backgroundColor: fg,
              backgroundImage: isAccent ? flute(20) : undefined,
              backgroundSize: isAccent ? `${w}px ${barH}px` : undefined,
              backgroundPosition: "left bottom",
            }}
          >
            <div
              style={{
                ...labelStyle,
                top: 12 * u - (barH - fillH),
                color: isAccent ? "#FFFFFF" : p.bg,
              }}
            >
              {lastLabel}
            </div>
          </div>
        </div>
      </div>
    );
  });

  const labels: ReactNode[] = [];
  LEVELS.forEach((lv, li) => {
    const el = splits[li];
    const inK = interpolate(
      t,
      [el.start + el.beat("labelIn"), el.start + el.beat("labelShown")],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
    const next = splits[li + 1];
    const outK = next
      ? interpolate(
          t,
          [next.start + next.beat("handover"), next.start],
          [0, 1],
          CLAMP,
        )
      : 0;
    if (!next && reg > 0) return;
    for (let g = 0; g < SEGS / lv.size; g++) {
      const j0 = g * lv.size;
      const op = inK * (1 - outK);
      if (op <= 0) continue;
      labels.push(
        <div
          key={`l${li}-${g.toString()}`}
          style={{
            ...labelStyle,
            left: xs[j0] + 14 * u,
            top: top + 12 * u,
            color: p.bg,
            opacity: op,
            transform: `translateY(${(1 - inK) * 6 * u}px)`,
          }}
        >
          {lv.label}
        </div>,
      );
    }
  });

  const words = splitWords(line, highlight);

  const pushAt = (tt: number) =>
    interpolate(tt, [pushEl.start, pushEl.end], [0.985, 1.01], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const push = pushAt(t);
  // The push carries the bar and the line; weighed by the ~1000px from the
  // centre to the furthest text. It runs past every piece's travel, so its
  // tilt covers the labels inside the pieces too.
  const pushing =
    Math.abs(pushAt(t + speed) - push) > 1e-6 ||
    Math.abs(push - pushAt(t - speed)) > 1e-6;

  return (
    <AbsoluteFill
      style={{
        background:
          background === "transparent" ? undefined : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${push})${glide(pushing)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <AbsoluteFill
            style={{
              clipPath: `inset(0 ${(1 - wipe) * 100}% 0 0)`,
            }}
          >
            {pieces}
            {labels}
          </AbsoluteFill>

          <div
            style={{
              position: "absolute",
              left: cx - barW * 0.5,
              width: barW,
              top: finalTop + barH + textGap,
              textAlign: "center",
              fontFamily,
              fontWeight: 400,
              fontSize: textSize,
              lineHeight: 1.02,
              letterSpacing: "-0.035em",
              color: fg,
              textWrap: "balance",
            }}
          >
            {words.map((w, i) => {
              const wordEl = tl.get(`word:${i}`);
              const k = interpolate(t, [wordEl.start, wordEl.end], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              return (
                <span key={`w${i.toString()}`}>
                  <span
                    style={{
                      display: "inline-block",
                      color: w.hl ? "transparent" : fg,
                      ...(w.hl
                        ? {
                            fontWeight: 500,
                            paddingRight: "0.04em",
                            backgroundImage: `linear-gradient(${172 + 10 * drift}deg, ${p.hl[0]} 8%, ${blue} 32%, ${p.hl[1]} 70%, ${p.hl[2]} 94%)`,
                            WebkitBackgroundClip: "text",
                            backgroundClip: "text",
                          }
                        : null),
                      opacity: k,
                      filter:
                        k < 0.99 ? `blur(${(1 - k) * 8 * u}px)` : undefined,
                      transform: `translateY(${(1 - k) * 18 * u}px)`,
                    }}
                  >
                    {w.text}
                  </span>
                  {i < words.length - 1 ? " " : null}
                </span>
              );
            })}
          </div>
        </AbsoluteFill>
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.55,
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The slow push on the whole scene, the bar wiping in, the bar splitting
// into halves, quarters and eighths, the pieces regrouping around the accent
// piece, and the line rising in word by word. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

export type FractionSplitElementId =
  | "push"
  | "wipe"
  | `split:${number}`
  | "regroup"
  | `word:${number}`;

export interface FractionSplitTimingProps {
  line?: string;
  highlight?: string;
  stagger?: number;
}

export const DEFAULT_LINE = "Renders in 1/8 the time.";
export const DEFAULT_HIGHLIGHT = "1/8";
export const DEFAULT_STAGGER = 3;

/** Each split: its first frame, its label and how many eighths a piece holds. */
export const LEVELS = [
  { at: 24, label: "1/2", size: 4 },
  { at: 50, label: "1/4", size: 2 },
  { at: 76, label: "1/8", size: 1 },
];
const REG = 104;
const REG_LEN = 26;
const TEXT_IN = REG + 12;
const WORD_RISE = 18;

/** The line as words, the highlight (and what is glued to it) as one. */
export function splitWords(line: string, highlight: string) {
  const idx = highlight ? line.indexOf(highlight) : -1;
  const words: { text: string; hl: boolean }[] = [];
  const pushWords = (s: string, hl: boolean) => {
    for (const w of s.split(/\s+/).filter(Boolean)) words.push({ text: w, hl });
  };
  if (idx >= 0) {
    pushWords(line.slice(0, idx), false);
    words.push({ text: highlight, hl: true });
    const rest = line.slice(idx + highlight.length);
    if (/^\S/.test(rest) && words.length) {
      const m = /^(\S+)(.*)$/.exec(rest);
      if (m) {
        words[words.length - 1] = {
          text: `${highlight}${m[1]}`,
          hl: true,
        };
        pushWords(m[2], false);
      }
    } else pushWords(rest, false);
  } else pushWords(line, false);
  return words;
}

// `push` scales the scene from its first frame to its end. `split:<i>`
// opens the boundaries of level `i` (the eighths open `spread` apart from the
// middle out); its labels rise from `labelIn` to `labelShown`, and fade out
// from `handover` (negative) before the next split. `regroup` moves the bar
// up and pulls the accent piece aside: the accent fills over `rise`, the
// other pieces drain from `drainAt` to `drainEnd`, `drainStep` apart, and the
// gradients drift over `drift`. `word:<i>` is a chain from inside the regroup.
export const fractionSplitTimeline = defineTimeline<
  FractionSplitElementId,
  FractionSplitTimingProps
>(
  ({
    line = DEFAULT_LINE,
    highlight = DEFAULT_HIGHLIGHT,
    stagger = DEFAULT_STAGGER,
  }) => {
    const words = splitWords(line, highlight);
    const elements: TimelineElement<FractionSplitElementId>[] = [
      {
        id: "push",
        lane: "Camera",
        label: "Push",
        start: 0,
        length: REG + REG_LEN + 40,
      },
      { id: "wipe", lane: "Bar", label: "Wipe", start: 2, length: 20 },
      ...LEVELS.map(
        (lv, i): TimelineElement<FractionSplitElementId> => ({
          id: `split:${i}`,
          lane: "Bar",
          label: lv.label,
          start: lv.at,
          length: (LEVELS[i + 1]?.at ?? REG) - lv.at,
          follows: i > 0 ? `split:${i - 1}` : undefined,
          beats: {
            spread: i === 2 ? 0.6 : 0,
            labelIn: 6,
            labelShown: 16,
            handover: -5,
          },
        }),
      ),
      {
        id: "regroup",
        lane: "Bar",
        label: "Regroup",
        start: REG,
        length: REG_LEN,
        follows: `split:${LEVELS.length - 1}`,
        beats: {
          rise: 16,
          drainAt: 2,
          drainEnd: 16,
          drainStep: 1.5,
          drift: REG_LEN + 50,
        },
      },
      ...words.map(
        (w, i): TimelineElement<FractionSplitElementId> => ({
          id: `word:${i}`,
          lane: "Line",
          label: w.text,
          start: TEXT_IN + i * stagger,
          length: WORD_RISE,
          follows: i > 0 ? `word:${i - 1}` : "regroup",
        }),
      ),
    ];
    return elements;
  },
);
